package net.battlespades.bot;
import java.nio.file.Path;
import java.util.*;
import java.util.function.DoubleSupplier;
import net.battlespades.physics.PlayerPhysics.Vector;
import static net.battlespades.bot.BotState.*;
import net.battlespades.bot.BotState.Observer;
/** Worker-owned collision/semantic snapshot, live deltas and layer-aware corridor guidance. */
public final class BotNavigationWorld {
    private static final double MAP_HEALTH=net.battlespades.catalog.SourceCatalog.load("bot-foundations").getDouble("map_block_health");
    private final Thread owner=Thread.currentThread();private final PlanningBudget budget;private final DoubleSupplier measured;private CompactVoxelMap map;private NavigationAtlas atlas;private Map<String,BotPrefabPolicy.Geometry> prefabGeometry=Map.of();private long epoch=-1,version=-1,base=-1,latest=-1;private final long[] columns=new long[512*512];private final BitSet dirty=new BitSet(512*512);private byte[] corridorSupports;private final Map<Cell,Double> health=new HashMap<>();private Observer observer;private double planningTime;private boolean planningRequested;
    public BotNavigationWorld(){this(null,()->System.nanoTime()/1e9);}public BotNavigationWorld(PlanningBudget budget,DoubleSupplier measured){this.budget=budget;this.measured=Objects.requireNonNull(measured);Arrays.fill(columns,-1);}
    private void owned(){if(Thread.currentThread()!=owner)throw new IllegalStateException("Navigation world outside worker");}public PlanningBudget budget(){owned();return budget;}public boolean ready(){owned();return map!=null;}public long epoch(){owned();return epoch;}public long version(){owned();return version;}public Optional<NavigationAtlas> atlas(){owned();return Optional.ofNullable(atlas);}
    public void load(MapSnapshot snapshot){owned();var geometry=new LinkedHashMap<String,BotPrefabPolicy.Geometry>();for(var g:snapshot.prefabGeometry())geometry.put(g.name(),g);prefabGeometry=Collections.unmodifiableMap(geometry);epoch=snapshot.mapEpoch();version=snapshot.topologyVersion();Arrays.fill(columns,-1);base=latest=version;map=null;atlas=null;dirty.clear();corridorSupports=null;health.clear();endPlanning(false);if(budget!=null)budget.reset();byte[] raw=snapshot.rawVxl();if(raw.length==0)return;var candidate=new CompactVoxelMap(raw,snapshot.sourceFormat());for(var change:snapshot.cells()){candidate.set(change.x(),change.y(),change.z(),change.solid());recordHealth(change);if(inside(change.x(),change.y()))dirty.set(change.y()*512+change.x());}map=candidate;boolean cacheable=snapshot.cells().isEmpty()&&!snapshot.sourceFormat().equals("classic64");try{atlas=NavigationAtlas.loadOrBuild(candidate,raw,cacheable&&!snapshot.mapDirectory().isEmpty()?Path.of(snapshot.mapDirectory()):null,cacheable?snapshot.mapName():"").atlas();}catch(RuntimeException invalid){atlas=null;}}
    private static boolean inside(int x,int y){return x>=0&&x<512&&y>=0&&y<512;}private void recordHealth(VoxelChange change){var cell=change.coordinate();if(change.solid()&&change.health()>0)health.put(cell,change.health());else health.remove(cell);}
    public Map<String,BotPrefabPolicy.Geometry> prefabGeometry(){owned();return prefabGeometry;}
    public int topSurface(int x,int y){owned();return map==null?240:map.surfaceZ(x,y);}
    public double blockHealth(int x,int y,int z){owned();return health.getOrDefault(new Cell(x,y,z),MAP_HEALTH);}
    public void apply(WorldDelta delta){owned();if(delta.mapEpoch()!=epoch||delta.topologyVersion()<version)return;if(latest!=version)base=-1;long next=delta.topologyVersion();if(next<0)base=-1;else for(var change:delta.cells()){if(inside(change.x(),change.y()))columns[change.y()*512+change.x()]=next;else base=-1;}if(map!=null)for(var change:delta.cells()){map.set(change.x(),change.y(),change.z(),change.solid());recordHealth(change);if(inside(change.x(),change.y()))dirty.set(change.y()*512+change.x());}version=latest=next;if(corridorSupports!=null&&map!=null)for(var c:delta.cells())if(inside(c.x(),c.y()))corridorSupports[c.y()*512+c.x()]=(byte)Math.min(255,map.surfaceZ(c.x(),c.y()));}
    public void beginPlanning(Observer observer,double now){owned();this.observer=observer;planningTime=now;planningRequested=false;}
    public boolean planningAvailable(){owned();if(budget==null||observer==null)return true;if(budget.wouldGrant(observer,planningTime))return true;budget.acquire(observer,planningTime);planningRequested=true;return false;}
    public void endPlanning(boolean cancelUnused){owned();if(cancelUnused&&!planningRequested&&observer!=null&&budget!=null)budget.cancel(observer);observer=null;}
    public boolean solid(int x,int y,int z){owned();return map==null||!inside(x,y)||z<0||z>=240||map.solid(x,y,z);}
    public boolean lineOfSight(Vector from,Vector to){owned();if(map==null)return false;double dx=to.x()-from.x(),dy=to.y()-from.y(),dz=to.z()-from.z(),distance=Math.sqrt(dx*dx+dy*dy+dz*dz);if(distance<=1e-6)return true;if(!Double.isFinite(distance))throw new IllegalArgumentException("Nonfinite sight ray");int steps=(int)Math.max(1,Math.min(384,Math.ceil(distance*2)));for(int i=1;i<steps;i++){double f=i/(double)steps;if(solid((int)Math.floor(from.x()+dx*f),(int)Math.floor(from.y()+dy*f),(int)Math.floor(from.z()+dz*f)))return false;}return true;}
    public Surface surface(int x,int y,double playerZ,int span,int clearance,boolean allowWater){owned();if(!inside(x,y))return null;if(!Double.isFinite(playerZ))throw new IllegalArgumentException("Nonfinite support height");int expected=(int)Math.rint(playerZ+2.25);if(allowWater&&expected>=238&&!solid(x,y,238)&&!solid(x,y,237))return new Surface(x,y,239);int col=y*512+x;if(atlas!=null&&!dirty.get(col)&&clearance==2){int support=atlas.primary(col);boolean water=(atlas.flags(col)&NavigationAtlas.WATER)!=0;if(support!=255&&atlas.layerCount(col)==1&&Math.abs(support-expected)<=Math.max(0,span)&&(allowWater||!water))return new Surface(x,y,support);}int low=Math.max(clearance,expected-Math.max(0,span)),high=Math.min(240,expected+Math.max(0,span)+1);var candidates=new ArrayList<Integer>();for(int z=low;z<high;z++)candidates.add(z);candidates.sort(Comparator.comparingInt(z->Math.abs(z-expected)));for(int support:candidates){if(support>=239&&!allowWater||!solid(x,y,support))continue;boolean clear=true;for(int offset=1;offset<=clearance;offset++)if(solid(x,y,support-offset)){clear=false;break;}if(clear)return new Surface(x,y,support);}return null;}
    public Surface surface(int x,int y,double playerZ,int span,boolean water){return surface(x,y,playerZ,span,2,water);}
    public List<Integer> supports(int x,int y,boolean water){owned();if(!inside(x,y)||map==null)return List.of();var result=new ArrayList<Integer>();for(int z=2;z<(water?240:239);z++)if(map.solid(x,y,z)&&!map.solid(x,y,z-1)&&!map.solid(x,y,z-2))result.add(z);return List.copyOf(result);}
    public Surface goalSurface(Vector goal,boolean water){owned();int x=(int)Math.floor(goal.x()),y=(int)Math.floor(goal.y());double gap=Double.POSITIVE_INFINITY;Integer best=null;for(int support:supports(x,y,water)){double candidate=Math.max(0,Math.max(support-2.25-goal.z(),goal.z()-support));if(candidate<gap){gap=candidate;best=support;}}return best==null?null:new Surface(x,y,best);}
    private static boolean finite(Vector point){return Double.isFinite(point.x())&&Double.isFinite(point.y())&&Double.isFinite(point.z());}
    private boolean changedNear(double x,double y,int reach,long before,Set<Integer> checked){int cx=(int)Math.floor(x),cy=(int)Math.floor(y);if(!inside(cx,cy))return true;int key=cy*512+cx;if(!checked.add(key))return false;for(int yy=Math.max(0,cy-reach);yy<Math.min(512,cy+reach+1);yy++)for(int xx=Math.max(0,cx-reach);xx<Math.min(512,cx+reach+1);xx++)if(columns[yy*512+xx]>before)return true;return false;}
    public boolean needsReplan(long before,Vector position,List<RouteStep> steps,boolean stuck){owned();if(base<0||before<base||before>version||latest!=version||steps.isEmpty())return true;var ahead=steps.subList(0,Math.min(64,steps.size()));if(stuck&&ahead.stream().anyMatch(s->s.affordance()!=Affordance.WALK&&s.affordance()!=Affordance.CROUCH||s.breach()!=null))return true;var checked=new HashSet<Integer>();if(changedNear(position.x(),position.y(),4,before,checked))return true;Vector previous=position;for(var step:ahead){var point=step.waypoint();if(!finite(previous)||!finite(point))return true;double span=Math.hypot(point.x()-previous.x(),point.y()-previous.y());if(span>1024)return true;int pieces=Math.max(1,(int)Math.ceil(span));for(int piece=0;piece<=pieces;piece++){double fraction=piece/(double)pieces;if(changedNear(previous.x()+(point.x()-previous.x())*fraction,previous.y()+(point.y()-previous.y())*fraction,1,before,checked))return true;}if(step.breach()!=null){var cells=new ArrayList<>(step.breach().blockingCells());cells.addFirst(step.breach().targetCell());for(var cell:cells)if(changedNear(cell.x()+.5,cell.y()+.5,1,before,checked))return true;}previous=point;}return false;}
    private Integer endpoint(Vector at,int radius,double vertical){Integer best=null;double bestScore=Double.POSITIVE_INFINITY;int px=(int)at.x(),py=(int)at.y();for(int y=Math.max(0,py-radius);y<Math.min(512,py+radius+1);y++)for(int x=Math.max(0,px-radius);x<Math.min(512,px+radius+1);x++){var s=surface(x,y,at.z(),(int)Math.ceil(vertical),false);double dz=s==null?Double.POSITIVE_INFINITY:Math.abs(s.position().z()-at.z());if(s!=null&&s.supportZ()<239&&dz<=vertical){double dx=x+.5-at.x(),dy=y+.5-at.y(),score=dx*dx+dy*dy+dz*dz;int node=y*512+x+s.supportZ()*512*512;if(score<bestScore||score==bestScore&&(best==null||node<best)){bestScore=score;best=node;}}}return best;}
    public Corridor corridor(Vector start,Vector goal,Set<Edge> blocked){owned();if(atlas==null)return null;if(corridorSupports==null){corridorSupports=new byte[512*512];for(int i=0;i<corridorSupports.length;i++)corridorSupports[i]=(byte)atlas.primary(i);if(map!=null)for(int col=dirty.nextSetBit(0);col>=0;col=dirty.nextSetBit(col+1))corridorSupports[col]=(byte)Math.min(255,map.surfaceZ(col%512,col/512));}Integer source=endpoint(start,1,1.5);var named=goalSurface(goal,false);Integer target;if(named==null)target=endpoint(goal,6,12.);else target=named.y()*512+named.x()+named.supportZ()*512*512;if(source==null||target==null)return null;var valid=new HashSet<Edge>();for(var edge:blocked)if(inside(edge.source().x(),edge.source().y())&&inside(edge.target().x(),edge.target().y()))valid.add(edge);var search=new SurfaceCorridorSearch(corridorSupports,512,512,source%(512*512),target%(512*512),valid,(x,y,support)->{var s=surface(x,y,support-2.25,2,false);return s==null?null:s.supportZ();},source/(512*512),target/(512*512),(x,y)->supports(x,y,false));return new Corridor(search);}
    public record RoutePlan(List<RouteStep> steps,boolean reachedSegmentGoal,int expansions,boolean deferred) {
        public RoutePlan { steps=List.copyOf(steps); }
    }
    private final BotRoutePlanner localPlanner=new BotRoutePlanner(this);
    private final BotWaterNavigation waterNavigation=new BotWaterNavigation(this);
    public BotWaterNavigation water() {owned();return waterNavigation;}
    public RoutePlan plan(Vector start,Vector goal,Set<Affordance> abilities,BotDigProfile dig,boolean allowWater,Set<Edge> blocked) {
        return plan(start,goal,abilities,dig,allowWater,blocked,true,true);
    }
    /** Recovery may bypass a useful ordinary segment to cost excavation at its boundary. */
    public RoutePlan plan(Vector start,Vector goal,Set<Affordance> abilities,BotDigProfile dig,boolean allowWater,Set<Edge> blocked,boolean recoverStart,boolean preferExistingPath) {
        owned();Objects.requireNonNull(start);Objects.requireNonNull(goal);
        abilities=Set.copyOf(abilities);blocked=Set.copyOf(blocked);planningRequested=true;
        if(budget==null)return localPlanner.plan(start,goal,abilities,dig,allowWater,blocked,null,recoverStart,preferExistingPath);
        var job=observer==null?null:budget.acquire(observer,planningTime);
        if(job==null)return new RoutePlan(List.of(),false,0,true);
        double began=measured.getAsDouble();
        try {return localPlanner.plan(start,goal,abilities,dig,allowWater,blocked,job,recoverStart,preferExistingPath);}
        finally {budget.finish(job,measured.getAsDouble()-began);}
    }
    public final class Corridor {
        private final SurfaceCorridorSearch search;private boolean deferred;private Corridor(SurfaceCorridorSearch search){this.search=search;}
        public boolean done(){owned();return search.done();}public boolean deferred(){owned();return deferred;}public int expansions(){owned();return search.expansions();}public List<Vector> path(){owned();return search.path();}public void exclude(Edge edge){owned();search.exclude(edge);}
        public void advance(){owned();if(search.done())return;if(budget==null){search.advance();return;}planningRequested=true;var job=observer==null?null:budget.acquire(observer,planningTime);deferred=job==null;if(job==null)return;double began=measured.getAsDouble();int before=search.expansions();try{job.beginSearch(512);search.advance();}finally{job.expansions(search.expansions()-before);budget.finish(job,measured.getAsDouble()-began);}}
    }
}
